INSERT INTO rule (id, ask, verdict, name, type, level, regex_source, regex_flags, why, law, fix) VALUES
('R01', '实习要交押金合法吗？', '不合法。《劳动合同法》第 9 条明确禁止用人单位要求劳动者提供担保或以其他名义收取财物。', '以押金／保证金名义收费', '押金类', '高', '(?:缴纳|交纳|收取|支付|预交|一次性交)[^。；\n]{0,12}(?:押金|保证金|风险金|抵押金)', '', '用人单位向劳动者收取押金、保证金，属于法律明确禁止的行为，交了也难要回，还容易被当成"违约抵押"。', '参见《劳动合同法》第 9 条：用人单位招用劳动者，不得扣押居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。', '删掉押金条款；已经交的，要求出具收据并全额退还，退还可作为继续谈的条件。'),
('R02', '实习押金说离职退，到期不给怎么办？', '押金本身就不该收，更不能不退。已交的可要求全额退还，保留转账记录与聊天记录。', '押金不予退还／抵扣工资', '押金类', '高', '(?:押金|保证金|风险金)[^。；\n]{0,12}(?:不予退还|概不退还|不退还|没收|抵扣|冲抵)', '', '把押金变成"随时可以没收"的钱，等于用你的钱给公司兜底，条款本身对你不利且缺乏法律依据。', '参见《劳动合同法》第 9 条；《劳动法》第 50 条：工资应当以货币形式按月支付给劳动者本人，不得克扣或者无故拖欠。', '整条删除；工资与押金必须分开结算，不得互相抵扣。'),
('R03', '入职要押身份证原件，能给他吗？', '不能。扣押身份证等证件违反《劳动合同法》第 9 条，对方无权代管。', '扣押身份证／学生证等证件原件', '押金类', '高', '(?:扣押|上交|交由|代为保管|统一保管|留存)[^。；\n]{0,10}(?:身份证|学生证|毕业证|学位证|护照|户口本)|(?:身份证|学生证|毕业证|学位证|护照|户口本)[^。；\n]{0,10}(?:原件)?[^。；\n]{0,6}(?:交由|上交|交予|统一保管|代为保管|留存)', '', '证件原件被公司保管，你就失去了行动自由：想走要证件、想投诉怕证件被扣。', '参见《劳动合同法》第 9 条：不得扣押劳动者的居民身份证和其他证件。', '改为"入职时出示原件核验，提交复印件"，并注明复印件仅用于入职备案。'),
('R04', '上班第一天要交服装费和工牌费正常吗？', '不正常。服装费、工牌费、工装押金都属于变相收取财物，同样在禁止范围内。', '以服装费／工牌费／工装押金名义收费', '押金类', '中', '(?:服装费|工牌费|工装费|工作服费|胸卡费|门禁卡押金|工装押金)', '', '这些费用本质仍是"入职先交钱"，与押金同理；正规单位的工作服、工牌由单位承担。', '参见《劳动合同法》第 9 条（不得以其他名义向劳动者收取财物）。', '要求改为公司统一配发、离职归还；已交的费用写入退还条款。'),
('R05', '公司指定医院让我自费体检，这钱该我出吗？', '常规入职体检费用应由单位承担；指定机构、指定项目再让你自费，是变相收费。', '指定医院自费体检并指定项目', '押金类', '中', '(?:指定|必须到|统一到)[^。；\n]{0,16}(?:医院|体检中心)[^。；\n]{0,12}(?:体检|检查)[^。；\n]{0,12}(?:自费|费用自理|费用由本人承担)', '', '职业健康检查费用依法由用人单位承担；指定自费体检常被当成变相收费。', '参见《职业病防治法》第 35 条（职业健康检查费用由用人单位承担）；《劳动合同法》第 9 条。', '改为"体检由公司统一安排并承担费用"，或明确凭票报销。'),
('R06', '不用交押金，但要交「诚信金」，是一回事吗？', '是一回事。名称换了，性质没变，只要是以入职为条件收的钱，都在禁止范围内。', '收取"诚信金""培训押金"等变相费用', '押金类', '高', '(?:诚信金|诚意金|就业保证金|入职保证金|培训押金|设备押金|资料押金)', '', '换个名字收钱，性质不变。用人单位以任何名义向劳动者收取财物都不被允许。', '参见《劳动合同法》第 9 条。', '一律不交；已交的保留转账记录与收据，作为后续投诉证据。'),
('R07', '还没上班就先扣一笔违约金，合法吗？', '没有依据。尚未提供劳动就先扣钱，属于变相收取财物。', '以"违约金"名义先行扣款', '押金类', '高', '(?:从工资中|直接从工资|先行扣除|预扣)[^。；\n]{0,12}(?:违约金|赔偿金|罚款)', '', '先扣钱再讲道理，你会失去谈判筹码；用人单位对劳动者罚款本身缺乏法律依据。', '参见《劳动法》第 50 条；《劳动合同法》第 25 条（除服务期、竞业限制外不得约定违约金）。', '删除"先行扣除"表述；有争议时走正常协商或仲裁程序，不得单方扣款。'),
('R08', '实习要自己交培训费，能交吗？', '岗位培训费用应由用人单位承担，把培训成本转嫁给学生是常见套路。', '培训费由学生自行承担', '培训贷', '高', '(?:培训费|培训费用|岗前培训费|技能培训费)[^。；\n]{0,14}(?:由|自理|自行承担|个人承担|学员承担|自付)', '', '岗前培训是用人单位的义务，把培训费转嫁给学生是最常见的"入职先付费"套路。', '参见《劳动合同法》第 9 条；《劳动法》第 68 条（用人单位应当建立职业培训制度，并承担相应费用）。', '要求培训费用由公司承担，并在协议中写明"不向学生收取任何培训费用"。'),
('R09', '面试让我办分期付培训费，这是骗局吗？', '高风险。正规招聘不会让求职者先办贷款，这类分期多为培训机构设计。', '诱导办理培训贷／分期付款', '培训贷', '高', '(?:培训贷|助学贷|教育分期|分期付款|办贷款|申请贷款|金融平台|信用分期|先学后付)', '', '一旦签了贷款合同，即使离职、即使公司跑路，还款义务仍然在你身上，征信也会受影响。', '参见《劳动合同法》第 9 条；《民法典》第 496 条（格式条款提供方应就重大利害关系条款作出提示说明）。', '不签任何贷款／分期协议；确需培训的，先确认费用主体与退款规则，要求书面写明。'),
('R10', '先培训后上岗、包就业，这种承诺能信吗？', '慎信。承诺写得越好越要落到书面，口头承诺在纠纷里几乎无法举证。', '"先培训后上岗、包就业"的话术', '培训贷', '高', '(?:先培训|培训合格后|培训结束)[^。；\n]{0,20}(?:上岗|安排就业|推荐就业|包就业|保证就业|包分配)', '', '"包就业"几乎不会写进合同违约责任，一旦不被录用，你已支付的培训费很难退回。', '参见《劳动合同法》第 9 条；《民法典》第 496 条。', '要求把"未安排上岗则全额退费"写成明确条款，并约定退费时限与违约金。'),
('R11', '不想干了要我赔全额培训费，合理吗？', '不合理。服务期违约金不得超过单位实际支出的培训费用，并按未履行期限分摊。', '违约金按培训费全额赔偿', '培训贷', '高', '(?:培训费|培训费用)[^。；\n]{0,12}(?:全额|全部|100%|双倍)[^。；\n]{0,8}(?:赔偿|赔付|支付|承担)', '', '服务期违约金的法定上限是"尚未履行部分所应分摊的培训费用"，全额赔偿没有依据。', '参见《劳动合同法》第 22 条：违约金不得超过用人单位提供的培训费用，且不得超过服务期尚未履行部分所应分摊的培训费用。', '按"已服务年限比例"约定，公式写清楚，上限不超过实际培训支出。'),
('R12', '培训费从第一个月工资里扣，可以吗？', '不可以。这等于是让员工承担本应由单位承担的经营成本。', '培训费直接从工资中扣除', '培训贷', '高', '(?:培训费|培训费用)[^。；\n]{0,14}(?:从工资|扣除|代扣|冲抵)', '', '工资是你的劳动报酬，未经同意大额扣款可能构成克扣工资。', '参见《劳动法》第 50 条；《工资支付暂行规定》第 15 条（不得克扣劳动者工资）。', '删除该条；如确需分摊，必须书面协商一致并单独签补充协议。'),
('R13', '试岗三天不给工资，是行业惯例吗？', '不是惯例，是不合法。只要提供了劳动就应支付报酬，不存在试岗不付钱的合法做法。', '试岗期／考察期不发工资', '无薪试岗', '高', '(?:试岗|试工期|考察期|试用考察)[^。；\n]{0,20}(?:无薪|无工资|不(?:予|再)?(?:发放|支付|付|给)(?:任何)?(?:工资|报酬|薪资)|没有报酬|不计薪)', '', '只要实际提供了劳动，就应当支付报酬。"免费试岗"是纯粹的用工成本转嫁。', '参见《劳动法》第 3 条（劳动者享有取得劳动报酬的权利）；第 50 条。', '删除"无薪"表述；试岗期按不低于当地最低工资标准支付，并签订书面协议。'),
('R14', '试用期只发七成工资，合法吗？', '有下限。《劳动合同法》第 20 条规定不得低于约定工资的 80%，且不得低于当地最低工资标准。', '试用期工资低于约定工资的 80%', '无薪试岗', '高', '(?:试用期|见习期)[^。；\n]{0,16}(?:工资|薪资|报酬)[^。；\n]{0,12}(?:[1-7]\d\s*%|半价|打对折)|(?:试用期|见习期)[^。；\n]{0,16}(?:工资|薪资|报酬)[^。；\n]{0,10}(?:低于|不及)[^。；\n]{0,8}(?:最低工资|正式工资)', '', '试用期工资有两个下限：不得低于本单位相同岗位最低档工资或合同约定工资的 80%，且不得低于当地最低工资标准。', '参见《劳动合同法》第 20 条；《劳动合同法实施条例》第 15 条。', '改为"试用期工资为转正工资的 80% 以上，且不低于当地最低工资标准"，写明具体金额。'),
('R15', '实习期能定六个月吗？上限是多久？', '有法定上限：三年以上或无固定期限合同试用期最长六个月；一年以上不满三年最长二个月；三个月以上不满一年最长一个月。', '试用期超过法定上限', '无薪试岗', '高', '(?:试用期|见习期)[^。；\n]{0,10}(?:6|六|9|九|12|十二)\s*个?月', '', '试用期长度受合同期限限制：三个月以上不满一年的不超过 1 个月，一年以上不满三年的不超过 2 个月，三年以上或无固定期限的不超过 6 个月；同一单位与同一劳动者只能约定一次试用期。', '参见《劳动合同法》第 19 条。', '按合同期限把试用期改到法定上限以内；超出部分按正式工资标准支付。'),
('R16', '说前两周是学习期不算工资，合理吗？', '不合理。学习期不是法律概念，只要在为单位提供劳动、接受管理，就属于用工。', '"培训期／学习期"不计工时', '无薪试岗', '高', '(?:培训期|学习期|岗前学习|实习期前置)[^。；\n]{0,16}(?:不计入|不算|不属于)[^。；\n]{0,10}(?:工作时间|工时|出勤)', '', '公司安排、要求你必须在场的培训，属于用工管理下的时间，不能靠一句"不算工时"就免掉报酬与工伤责任。', '参见《劳动法》第 3 条、第 50 条；《工伤保险条例》第 14 条。', '删除"不计工时"；培训期间正常计薪、计入考勤，并明确工伤责任由单位承担。'),
('R17', '公司说转正才签合同，之前不签，行吗？', '不行。《劳动合同法》第 10 条规定应当自用工之日起一个月内订立书面劳动合同。', '试用期不签书面协议／转正后再签', '无薪试岗', '高', '(?:试用期|转正|考核合格)[^。；\n]{0,14}(?:再签|后签订|之后签|另行签订|不签订书面)', '', '用工之日起就应订立书面劳动合同，最迟不超过一个月。先干后签，出了纠纷你手里没有证据。', '参见《劳动合同法》第 10 条：已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立；第 82 条（满一个月不满一年未签，应支付二倍工资）。', '要求入职当天签书面协议，写明岗位、地点、报酬、期限；拒签的留好工作痕迹。'),
('R18', '三方协议写了五千违约金，毁约要赔吗？', '可以约定，但金额应与实际损失相当；明显过高的，可主张调减。', '三方协议约定违约金', '违约金', '高', '(?:三方协议|就业协议)[^。；\n]{0,20}(?:违约金|违约赔偿|违约责任)', '', '三方协议里的违约金并非当然有效：如果单位未提供专项培训费用、也未约定竞业限制，高额违约金很难得到支持，但签了会先卡住你的档案与派遣。', '参见《劳动合同法》第 25 条：除本法第 22 条和第 23 条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。', '争取删除或把金额压到象征性数字；签字前把"违约金金额、触发条件"逐字读一遍。'),
('R19', '服务期违约金怎么算才是合法的？', '不得超过单位实际支出的培训费用，并按未履行的服务期限比例分摊。', '服务期违约金未按比例分摊', '违约金', '中', '(?:服务期|服务年限|最低服务)[^。；\n]{0,16}(?:违约金|赔偿)[^。；\n]{0,12}(?:全额|全部|一次性)', '', '服务期违约金应按"尚未履行部分"分摊，且总额不得超过单位实际支出的培训费用。', '参见《劳动合同法》第 22 条。', '写明培训费用总额、服务期长度、逐年递减的分摊公式。'),
('R20', '合同里违约金写五万，签了就要赔吗？', '不是想写多少就多少。违约金应与实际损失相当，明显过高的可请求调减。', '单方设定高额违约金', '违约金', '高', '(?:违约)[^。；\n]{0,10}(?:金|赔偿)[^。；\n]{0,12}(?:[1-9]\d{3,}\s*元|[1-9]\d?\s*万元|十倍|双倍)', '', '动辄数千上万元的违约金，与学生实习报酬严重不对等，是典型的"用合同吓住你"。', '参见《劳动合同法》第 25 条；《民法典》第 585 条（违约金过分高于损失的，可请求适当减少）。', '把金额改成与实际损失挂钩，或直接删除；已签的保留证据，主张调整。'),
('R21', '合同说离职就算违约，是这样吗？', '不是。劳动者依法享有解除权，把正常离职一律定为违约的条款通常无效。', '离职即视为违约并赔偿', '违约金', '高', '(?:离职|辞职|解除协议|提前离开)[^。；\n]{0,14}(?:视为违约|构成违约|需支付违约金|须赔偿)', '', '除服务期与竞业限制两种情形外，用人单位不能约定由劳动者承担违约金；正常辞职是法定权利。', '参见《劳动合同法》第 25 条、第 37 条（提前 30 日书面通知即可解除，试用期内提前 3 日）。', '删除"离职即违约"；改为提前书面通知并完成工作交接。'),
('R22', '让我签竞业限制又不给补偿，有效吗？', '对你很难有约束力。竞业限制必须约定并按月支付经济补偿，不付补偿的条款难以执行。', '竞业限制未约定经济补偿', '违约金', '中', '(?:竞业限制|竞业禁止|不得从事|不得入职)[^。；\n]{0,30}(?:补偿|经济补偿|补偿金)', '', '有竞业限制却避谈补偿，等于单方面限制你的就业自由；无补偿的竞业限制条款容易被认定无效，但争议成本在你身上。', '参见《劳动合同法》第 23 条、第 24 条：竞业限制期限内应按月给予经济补偿；限制期限不得超过二年。', '写明每月补偿金额、发放时间、限制范围与期限（不超过 2 年），并约定未支付补偿时的解除权。'),
('R23', '保密协议写永久有效，合理吗？', '保密义务可以有期限，「永久」「一切信息」这类范围过宽的约定难以执行，签前要谈具体范围。', '保密协议无期限／范围过宽', '违约金', '中', '(?:保密)[^。；\n]{0,16}(?:永久|无限期|长期有效|终身|一切|所有信息)', '', '把"一切信息永久保密"写进协议，实际是把择业与表达空间都锁死；保密范围应当具体、期限应当合理。', '参见《劳动合同法》第 23 条；《反不正当竞争法》第 9 条（商业秘密须符合法定要件）。', '把保密信息列举清楚（技术资料、客户名单等），约定期限（如离职后 2 年）与例外情形（已公开信息）。'),
('R24', 'HR 在三方上手写加了一条，算数吗？', '只要双方签字确认就有效。所以签字前必须逐条看清，空白处不要留，也不要签完再让对方补。', '三方协议上手写补充条款', '违约金', '高', '(?:手写|补充条款|附加条款|另附)[^。；\n]{0,16}(?:协议|条款|约定)', '', '手写条款与印刷条款冲突时容易扯皮，且手写部分常被夹带"放弃权利""同意调配"等内容。', '参见《民法典》第 496 条（格式条款的提示说明义务）；第 490 条（合同成立需双方签名盖章）。', '手写内容必须双方签字确认、逐条抄进正式文本；不接受只在单位那份上手写。'),
('R25', '实习期公司不交社保，正常吗？', '要分清：真正的在校实习通常不建立劳动关系；但以实习名义长期用工、按月发薪、固定考勤的，性质另说。', '实习／试用期间不缴社保', '社保', '中', '(?:实习|试用|见习)[^。；\n]{0,14}(?:(?:不|未|无)[^。；\n]{0,6}(?:缴纳|缴)|不缴|无需缴纳)[^。；\n]{0,8}(?:社保|社会保险|五险)', '', '是否缴社保关键看是否建立劳动关系，而不是看公司给你贴的"实习"标签；认定劳动关系后不缴社保要补缴并可能被处罚。', '参见《社会保险法》第 58 条：用人单位应当自用工之日起三十日内为其职工申请办理社会保险登记。', '要求写明"依法缴纳社会保险"；如对方坚持不缴，把这条作为是否入职的判断依据。'),
('R26', '公司让我签自愿放弃社保，签了会怎样？', '承诺无效。社会保险是法律强制性规定，不能通过约定放弃。', '要求签署"自愿放弃社保"承诺', '社保', '高', '(?:(?:自愿|主动|同意)放弃|放弃缴纳|自动放弃|不参加)[^。；\n]{0,10}(?:社保|社会保险|五险|养老保险)|(?:社保|社会保险|五险)[^。；\n]{0,12}(?:自愿放弃|放弃缴纳|不再缴纳)', '', '社保是法定义务，不能由劳动者"自愿放弃"；签了这张纸，出事时照样没有保障，而公司仍可能被追缴。', '参见《社会保险法》第 58 条、第 60 条；《劳动合同法》第 26 条（违反法律强制性规定的条款无效）。', '不签放弃承诺；如公司以补贴代替，要求把"补缴社保"写进协议。'),
('R27', '社保钱全从我工资里扣，对吗？', '不对。社保由单位和个人按比例分担，全部转嫁给个人不合法。', '社保费用全部由个人承担', '社保', '中', '(?:社保|社会保险)[^。；\n]{0,14}(?:由个人|个人全额|个人承担|从工资中全额扣除)', '', '社保由单位和个人按比例分担，单位应缴部分转嫁给个人属于变相降薪。', '参见《社会保险法》第 60 条：用人单位应当自行申报、按时足额缴纳社会保险费。', '核对工资条上的"个人缴纳"比例，超过法定个人比例的部分要求补回。'),
('R28', '上班受伤公司说责任自负，怎么办？', '工伤责任由用人单位承担，约定责任自负的条款无效。及时保留就医记录与在场证明。', '工伤责任推给个人', '社保', '高', '(?:工伤|工作受伤|意外伤害)[^。；\n]{0,20}(?:自行负责|个人承担|与公司无关|公司不承担责任|概不负责)', '', '工伤认定与赔偿是法定责任，不能通过合同条款推给个人；这类免责条款通常无效。', '参见《工伤保险条例》第 14 条、第 17 条；《劳动合同法》第 26 条。', '删除免责表述；要求写明"发生工伤按《工伤保险条例》处理"，并保留考勤、工作安排记录。'),
('R29', '一直叫我实习生，其实天天正常上班，算劳动关系吗？', '看实质不看名头：固定考勤、按月发薪、接受管理、从事单位业务的，可能构成事实劳动关系。', '以"实习"名义规避劳动关系', '社保', '高', '(?:以实习|实习名义|按实习|实习身份)[^。；\n]{0,26}(?:不建立劳动关系|不属于劳动关系|不签订劳动合同|不缴)', '', '是不是劳动关系看实际用工：是否接受管理、是否有报酬、是否从事单位业务。贴"实习"标签不能改变性质。', '参见《关于确立劳动关系有关事项的通知》（劳社部发〔2005〕12 号）第一条；《劳动合同法》第 7 条、第 10 条。', '按实际用工签合同、发工资、缴社保；至少要求书面写明工作内容与报酬。'),
('R30', '社保按最低标准交，会影响我什么？', '会直接影响未来的养老、医疗报销与公积金贷款额度，是长期隐患。', '社保基数按最低标准申报', '社保', '低', '(?:社保|社会保险)[^。；\n]{0,12}(?:最低基数|最低标准|按最低|下限缴纳)', '', '缴费基数应按本人工资申报，长期按最低基数缴，会影响你未来的医保报销与养老待遇。', '参见《社会保险法》第 60 条、第 62 条。', '核对工资条与社保缴费记录，发现基数不符可向社保经办机构反映。'),
('R31', '加班没有加班费，能要回来吗？', '能。安排加班就应支付加班费，《劳动法》第 44 条有明确的倍数标准。', '加班不支付加班费', '加班', '高', '(?:加班费|加班|延时工作|延长工作时间|超时工作)[^。；\n]{0,20}(?:不(?:再|另行|另|予|另行支付|再另行|再另)?[^。；\n]{0,4}(?:支付|计发|发放|计算|给)?加班费|无加班费|没有加班费|不给加班费|不计加班费|不另计|(?:不再另行|不再|不另)[^。；\n]{0,4}(?:支付|发放|计发)|(?:包含|含|计入)在?[^。；\n]{0,8}(?:工资|薪酬|月薪|薪金))', '', '加班费是法定报酬：工作日 1.5 倍、休息日 2 倍、法定节假日 3 倍。', '参见《劳动法》第 44 条；《劳动合同法》第 31 条（安排加班应支付加班费）。', '删除"无加班费"；要求写明加班审批流程与计薪方式。'),
('R32', '一个月加班四十多个小时，超了吗？', '超了。《劳动法》第 41 条规定一般每日不超过一小时，特殊原因每日不超过三小时、每月不超过三十六小时。', '月加班超过 36 小时', '加班', '高', '(?:每月|月均|一个月)[^。；\n]{0,10}(?:加班|加班时长)[^。；\n]{0,10}(?:4\s*0|4\s*5|5\s*0|6\s*0|[5-9]\d)\s*小时', '', '延长工作时间一般每日不超过 1 小时，特殊原因每日不超过 3 小时，每月不得超过 36 小时。', '参见《劳动法》第 41 条。', '把排班控制在法定上限内；超时部分保留打卡记录，作为主张加班费的证据。'),
('R33', '不加班就算旷工扣钱，合法吗？', '不合法。拒绝违法超时加班不能按旷工处理，更不能因此扣工资。', '强制加班／不加班算旷工', '加班', '高', '(?:不加班|拒绝加班|未加班)[^。；\n]{0,14}(?:视为旷工|按旷工|扣发工资|扣除工资|视为违纪)', '', '加班需与劳动者协商，强制加班并用旷工处罚，属于变相强迫劳动。', '参见《劳动法》第 41 条、第 43 条（用人单位不得违反本法规定延长劳动者的工作时间）。', '删除该条；保留"拒绝违法加班"的书面沟通记录。'),
('R34', '节假日加班只给调休不给钱，行吗？', '不行。法定节假日加班应支付不低于 300% 的工资，不能用调休替代。', '法定节假日加班只给调休', '加班', '中', '(?:法定节假日|节假日)[^。；\n]{0,20}(?:调休|补休|安排休息)[^。；\n]{0,10}(?:代替|替代|不再支付)', '', '休息日加班可以安排补休，但法定节假日加班必须支付 3 倍工资，不能用调休替代。', '参见《劳动法》第 44 条第（三）项。', '改为"法定节假日加班按 300% 支付工资"；休息日加班可协商补休。'),
('R35', '公司说值班不算加班，这说法对吗？', '不对。值班不能成为规避加班费的名义，实质是加班的就应按加班计算。', '"值班不算加班"', '加班', '中', '(?:值班|驻场|留守)[^。；\n]{0,14}(?:不算加班|不视为加班|不计加班)', '', '如果值班期间仍要从事本职工作或受考勤管理，"值班"二字改变不了加班的性质。', '参见《劳动法》第 41 条、第 44 条。', '要求按实际工作内容认定；至少写清值班补贴标准与休息安排。'),
('R36', '加班要审批，没审批就不算加班吗？', '审批是内部流程，不能否定客观存在的加班事实；考勤记录、工作群消息都是证据。', '未审批即不认加班', '加班', '中', '(?:未经|未通过)[^。；\n]{0,8}(?:审批|批准|申请)[^。；\n]{0,10}(?:不视为加班|不算加班|不予认定)', '', '把"加班审批"当作唯一认定标准，实践中会被用来否认实际加班事实，你需要自己保留证据。', '参见《劳动法》第 44 条；《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》第 42 条（加班事实的举证责任）。', '保留打卡记录、工作群消息、任务排期截图；要求审批流程留痕。'),
('R37', '试用期加班有加班费吗？', '有。加班费与是否在试用期无关。', '试用期／实习期不发加班费', '加班', '高', '(?:试用期|实习期|见习期)[^。；\n]{0,16}(?:无加班费|不支付加班费|不另计加班)', '', '试用期是劳动关系的一部分，加班同样要付加班费。', '参见《劳动法》第 44 条；《劳动合同法》第 20 条。', '删除；试用期加班按同一标准计薪。'),
('R38', '实习不签协议只口头说，有风险吗？', '有。没有书面约定，工资、岗位、期限全靠对方口头，出问题时几乎无法举证。', '不签书面协议／只做口头约定', '合同文本', '高', '(?:口头|口说|口头约定|不签订书面|无需签订|不必签订)[^。；\n]{0,14}(?:协议|合同|约定)?', '', '没有书面文本，工资、岗位、期限都只是"对方说的"，发生争议时举证极难。', '参见《劳动合同法》第 10 条；第 82 条（未签书面合同应支付二倍工资）。', '坚持签书面协议；对方不签的，用微信确认岗位、工资、上下班时间并保存记录。'),
('R39', '让我先在空白合同上签字，能签吗？', '绝不能签。空白处事后可以填任何内容，签字即视为认可。', '空白合同先签字', '合同文本', '高', '(?:空白|未填写|留空)[^。；\n]{0,10}(?:合同|协议)[^。；\n]{0,12}(?:先签|签字|盖章后)', '', '空白处事后可以填任何内容，你等于把解释权交了出去。', '参见《民法典》第 490 条、第 496 条。', '拒绝签空白文本；签字前用手机拍下每一页，空白处画斜线或注明"以下空白"。'),
('R40', '实习协议和劳动合同有什么区别？', '法律性质不同。实习协议不能替代劳动合同，用实习协议规避劳动关系是常见做法。', '实习协议冒充劳动合同', '合同文本', '高', '(?:实习协议|实习合同|实践协议)[^。；\n]{0,20}(?:等同|视为|代替)[^。；\n]{0,8}(?:劳动合同|劳动关系)|(?:签订实习协议)[^。；\n]{0,16}(?:不缴纳社保|不适用劳动法)', '', '协议叫什么名字不重要，关键看实际用工；用"实习协议"规避劳动法义务，是常见套路。', '参见《劳动合同法》第 7 条、第 10 条；劳社部发〔2005〕12 号第一条。', '按实际关系签合同；接受实习协议的，至少写明报酬、工时、安全责任。'),
('R41', '面试承诺转正涨薪，没写进合同算数吗？', '很难举证。口头承诺要落到纸面，否则纠纷时基本只能靠录音与聊天记录。', '口头承诺转正／承诺薪资', '合同文本', '中', '(?:口头承诺|承诺|保证)[^。；\n]{0,14}(?:转正|转编制|涨薪|调薪)[^。；\n]{0,10}(?:不写入|无需写入|另行通知)?', '', '"表现好就转正""转正后涨到多少"如果不进合同，随时可以变。', '参见《劳动合同法》第 17 条（劳动合同应具备劳动报酬等条款）；《民法典》第 469 条。', '把转正条件、转正后薪资写进书面协议，并约定未兑现的处理方式。'),
('R42', '合同写公司可以随时调岗调薪，合理吗？', '不合理。调岗调薪属于对合同的重大变更，应协商一致。', '单方调岗／调薪／调地点', '合同文本', '高', '(?:公司|单位|甲方)[^。；\n]{0,12}(?:有权|可根据|可随时|有权随时|可以单方|视情况|视经营需要)[^。；\n]{0,12}(?:调整|变更|调动|安排)[^。；\n]{0,8}(?:岗位|薪资|工作地点|工资|工作内容)', '', '岗位与报酬是合同核心条款，变更有严格条件；"公司有权单方调整"等于把合同变成可随时改的纸。', '参见《劳动合同法》第 35 条（变更劳动合同应协商一致并采用书面形式）；第 26 条。', '改为"调整岗位需双方协商一致并书面确认"；保留原岗位与薪资的书面记录。'),
('R43', '实习协议里全是员工管理规定，正常吗？', '要警惕。这说明对方可能两头占：用实习名义规避社保与最低工资，又用员工制度管你。', '劳动关系与实习关系混同', '合同文本', '中', '(?:同时|既|一边)[^。；\n]{0,12}(?:实习|见习)[^。；\n]{0,12}(?:又|并)[^。；\n]{0,12}(?:正式|全职|劳动合同)', '', '一份文本里既说实习又说正式用工，出了事双方各挑对自己有利的解释。', '参见《劳动合同法》第 7 条、第 10 条。', '只保留一种关系定性，其余表述删除；报酬、工时、社保按该定性执行。'),
('R44', '合同只签一份，公司收走了，可以吗？', '不行。《劳动合同法》第 16 条规定劳动合同文本由用人单位和劳动者各执一份。', '合同只签一份由公司留存', '合同文本', '中', '(?:合同|协议)[^。；\n]{0,10}(?:一式一份|仅公司|由公司保存|不予返还|不交给乙方)', '', '手里没有原件，等于没有合同。争议时你连条款内容都无法举证。', '参见《劳动合同法》第 16 条：劳动合同文本由用人单位和劳动者各执一份。', '要求一式两份、双方各持一份并盖章；拿不到原件的，拍照并保留签订过程的记录。'),
('R45', '合同背面一堆小字条款，要一条条看吗？', '要看。格式条款排除你主要权利的可以主张无效，但前提是你能说明对方没有提示你注意。', '格式条款排除你的权利', '合同文本', '中', '(?:最终解释权|概不负责|不承担任何责任|放弃|无权要求)[^。；\n]{0,16}(?:解释|责任|索赔|赔偿|追究)', '', '"最终解释权归公司""公司不承担任何责任"这类单方免责条款，法律上通常不产生效力，但会拖长你的维权时间。', '参见《民法典》第 496 条、第 497 条（不合理免除自身责任的格式条款无效）；《劳动合同法》第 26 条。', '要求删除或改成双向责任；签字前把免责条款逐条圈出来问清楚。'),
('R46', '合同没写工资多少和哪天发，正常吗？', '不正常。工资数额、支付时间与方式是劳动合同的必备条款。', '未写明工资数额与发放时间', '合同文本', '中', '(?:工资|薪资|报酬)[^。；\n]{0,10}(?:面议|另行约定|按公司规定|视情况|以实际发放为准)', '', '薪资"面议"、发放"按公司规定"，等于把最核心的经济条款留白。', '参见《劳动合同法》第 17 条（劳动合同应当具备劳动报酬条款）。', '写明具体金额、发放日（如每月 15 日）、发放方式与扣款项目。'),
('R47', '公司可以随时辞退我不给补偿，合法吗？', '不合法。解除需要法定理由与程序，约定随时解除且不补偿的条款通常无效。', '约定公司可随时解除且不补偿', '合同文本', '中', '(?:公司|单位|甲方)[^。；\n]{0,10}(?:可随时|有权随时)[^。；\n]{0,8}(?:解除|终止)[^。；\n]{0,12}(?:无需|不予|不支付)[^。；\n]{0,8}(?:补偿|赔偿|通知)', '', '解除劳动合同有法定条件与程序，"随时解除不补偿"剥夺了你的法定权利。', '参见《劳动合同法》第 39 条、第 40 条、第 46 条（经济补偿情形）、第 87 条（违法解除赔偿）。', '改为按法定情形解除；写明解除需提前通知并依法支付经济补偿。'),
('R48', '合同上没有公司名和公章，有效吗？', '风险极大。主体不明、没有公章，维权时连告谁都说不清，签前必须核对营业执照名称。', '合同无公司主体信息／未盖章', '合同文本', '中', '(?:无需盖章|不盖章|暂不盖章|以签字为准)[^。；\n]{0,10}(?:生效|成立)?', '', '没有公章、没有统一社会信用代码，你甚至无法确认对方是谁，投诉与起诉都找不到主体。', '参见《民法典》第 490 条；《劳动合同法》第 16 条（劳动合同由用人单位与劳动者签字或者盖章生效）。', '要求加盖公章并写明公司全称、地址、统一社会信用代码、联系人。'),
('R49', '合同约定去外地打官司，我得去吗？', '约定管辖不能随意剥夺你的诉权，明显不便、加重你负担的条款可以主张无效。', '争议解决约定异地仲裁／法院', '合同文本', '低', '(?:争议|纠纷)[^。；\n]{0,16}(?:提交|由)[^。；\n]{0,16}(?:仲裁委员会|人民法院)[^。；\n]{0,8}(?:仲裁|管辖)', '', '劳动争议一般由劳动合同履行地或用人单位所在地的仲裁委管辖，约定到外地会增加你的维权成本（该约定通常也无效）。', '参见《劳动争议调解仲裁法》第 21 条；《民事诉讼法》第 35 条。', '改为"由劳动合同履行地劳动争议仲裁委员会管辖"。'),
('R50', '合同写自愿放弃仲裁和诉讼，有效吗？', '无效。诉讼与仲裁是法定权利，事先约定放弃的条款不受支持。', '约定放弃诉讼／仲裁权利', '合同文本', '高', '(?:放弃|不再)[^。；\n]{0,10}(?:仲裁|诉讼|起诉|申诉)[^。；\n]{0,6}(?:权利|救济)?', '', '诉权是法定权利，不能靠合同条款一次性放弃；但签了会增加你心理压力与举证难度。', '参见《劳动合同法》第 26 条（排除劳动者权利的条款无效）；《劳动争议调解仲裁法》第 2 条。', '删除该条；保留合同原件与工资流水。'),
('R51', '签一年合同试用期三个月，对吗？', '不对。试用期长短必须与合同期限匹配，超限部分要按已履行的期限支付赔偿金。', '合同期限与试用期不匹配', '合同文本', '中', '(?:合同期|期限)[^。；\n]{0,10}(?:三个月|3\s*个月|半年|6\s*个月)[^。；\n]{0,14}(?:试用期)[^。；\n]{0,10}(?:2|两|3|三)\s*个?月', '', '合同期不满三个月的不得约定试用期；三个月以上不满一年的试用期不得超过一个月。', '参见《劳动合同法》第 19 条。', '按法定期限重新约定试用期。'),
('R52', '工资发现金、微信转账，没工资条怎么办？', '很难证明工资标准与发放事实，一旦欠薪、算工伤都很被动。要求银行代发并留存工资条。', '工资以现金／私人转账发放且无凭证', '合同文本', '中', '(?:现金|微信转账|支付宝转账|私人账户|个人账户)[^。；\n]{0,12}(?:发放工资|发工资|支付工资|结算工资)', '', '没有工资流水与工资条，"我在这里上班、月薪多少"都难以证明。', '参见《工资支付暂行规定》第 6 条（用人单位必须书面记录支付工资的数额、时间等并保存两年以上）。', '要求银行代发并保留工资条；现金发放的，每次让单位出具签收单并自己拍照。'),
('R53', '合同说离职要提前 90 天，必须遵守吗？', '没有法律依据。法定通知期是提前三十日，试用期内提前三日。', '离职需提前 90 天／超长通知期', '离职', '高', '(?:离职|辞职|解除)[^。；\n]{0,14}(?:提前)[^。；\n]{0,8}(?:6\s*0|9\s*0|一百二十|120)\s*(?:天|日)', '', '法定通知期是提前 30 日（试用期 3 日），约定 90 天没有法律依据，且会限制你换工作。', '参见《劳动合同法》第 37 条。', '改为"提前 30 日书面通知，试用期内提前 3 日"。'),
('R54', '不干满就说扣我实习证明，能扣吗？', '不能。实习证明与毕业材料属于你个人，用它要挟涉嫌违法。', '以扣押实习证明／毕业材料要挟', '离职', '高', '(?:实习证明|实践证明|鉴定表|毕业材料)[^。；\n]{0,14}(?:不予出具|不给开具|扣留|暂不发放|离职后再说)', '', '实习证明是学校认定学分与毕业的依据，被卡住往往只能忍气吞声。', '参见《劳动合同法》第 50 条（用人单位应当在解除或者终止劳动合同时出具证明）；第 89 条。', '入职时就约定出具时间与内容模板；离职前把工作交接清单与证明一并落实。'),
('R55', '提出离职，公司扣我当月工资，行吗？', '不行。已提供的劳动必须结清工资，扣发属于克扣工资。', '离职扣发当月工资', '离职', '高', '(?:离职|辞职|未满|提前离开)[^。；\n]{0,14}(?:不予结算|不结算|扣发|不发|扣押)[^。；\n]{0,8}(?:工资|报酬|薪资)', '', '已经提供的劳动必须结清报酬，离职不是扣工资的理由。', '参见《劳动法》第 50 条；《工资支付暂行规定》第 9 条（解除或终止劳动合同时一次付清工资）。', '写明"离职时按实际工作日一次性结清工资"。'),
('R56', '离职要我交培养费，这钱该给吗？', '没有法律依据的培养费可以拒付；违约金需要有约定且与实际损失相当。', '离职需缴"培养费""违约金"', '离职', '高', '(?:离职|辞职)[^。；\n]{0,16}(?:培养费|培训赔偿|补偿公司|缴纳违约金|支付违约金)', '', '没有专项培训支出、没有竞业限制，就不能约定离职赔偿。', '参见《劳动合同法》第 25 条、第 22 条。', '删除；如确有培训支出，要求出示费用凭证并按分摊公式计算。'),
('R57', '交接没做完就不发工资，合法吗？', '不合法。交接是义务，但不能成为不发工资的理由。', '离职不办交接即视为放弃工资', '离职', '中', '(?:未完成交接|不办理交接|拒不移交)[^。；\n]{0,14}(?:视为|按|不予)[^。；\n]{0,8}(?:放弃|扣发|不发)[^。；\n]{0,6}(?:工资|报酬)?', '', '交接与工资是两件事，用扣工资逼交接属于克扣工资。', '参见《劳动法》第 50 条；《劳动合同法》第 50 条（办理工作交接时支付经济补偿）。', '把交接清单与工资结算分开约定，工资按实际出勤结算。'),
('R58', '公司不给离职证明，影响我下份工作吗？', '应当出具，这是法定义务。扣档案更要及时向人社部门反映。', '不出具离职证明／扣档案', '离职', '中', '(?:离职证明|解除证明|档案)[^。；\n]{0,14}(?:不予出具|扣押|暂缓|不转出|留在公司)', '', '离职证明与档案转移是法定义务，被卡住会影响下一份工作与升学。', '参见《劳动合同法》第 50 条（十五日内办理档案和社会保险关系转移手续）。', '要求离职当日出具证明，并在协议中写明办理时限。'),
('R59', '试用期想走，要赔钱吗？', '不需要。试用期内提前三日通知即可解除，除非另有专项培训服务期的合法约定。', '试用期内离职需赔偿', '离职', '高', '(?:试用期)[^。；\n]{0,14}(?:离职|辞职)[^。；\n]{0,12}(?:赔偿|违约金|扣款)', '', '试用期内提前 3 日通知即可解除，不需要赔偿。', '参见《劳动合同法》第 37 条。', '删除；改为"试用期内提前 3 日书面通知即可解除"。'),
('R60', '没干满一年就没有年终奖，正常吗？', '看约定与制度。年终奖属于单位自主范围，但已明确的发放条件不能随意更改。', '"未干满一年不发年终奖／绩效"', '离职', '低', '(?:未满|不满|不足)[^。；\n]{0,8}(?:一年|1\s*年|半年)[^。；\n]{0,14}(?:不发|不予发放|取消)[^。；\n]{0,8}(?:年终奖|绩效|奖金)', '', '年终奖规则应当事先明确；已产生的劳动报酬不能因为离职就归零。', '参见《劳动法》第 46 条（工资分配遵循按劳分配、同工同酬）；《工资支付暂行规定》第 3 条。', '要求写明年终奖计算方式与在职月份的折算规则。'),
('R61', '公司说我自动离职，工资全扣，怎么办？', '自动离职不是法定概念，按旷工扣光全部工资缺乏依据，可以向劳动保障监察投诉。', '"自动离职"按旷工处理并扣发全部工资', '离职', '中', '(?:自动离职|擅自离岗|未办手续)[^。；\n]{0,16}(?:按旷工|视为旷工|全部扣除|不予结算)', '', '"自动离职"不是法定概念，用它清零工资与工龄，属于单方加重你的责任。', '参见《劳动合同法》第 50 条；《劳动法》第 50 条。', '改为按法定程序解除并结算工资；保留请假、沟通记录。'),
('R62', '说我表现不合格就直接辞退，要补偿吗？', '单位要举证。以不符合录用条件为由解除，必须事先明确标准并拿出证据。', '"表现不合格可随时终止且无补偿"', '离职', '中', '(?:考核不合格|表现不佳|不符合要求)[^。；\n]{0,16}(?:随时终止|立即辞退|直接解除|不予补偿)', '', '"不符合录用条件"需要事先明确标准并举证，不能事后一句"不合格"就辞退。', '参见《劳动合同法》第 39 条（试用期被证明不符合录用条件）、第 40 条；第 21 条（试用期解除需说明理由）。', '要求写明录用条件与考核标准；被辞退时索要书面解除通知。'),
('R63', '实习期间做的作品，著作权归谁？', '可以约定，但「一律无条件归公司、不署名不付酬」显失公平；署名权依法归作者。', '作品／创意成果著作权无条件归公司', '合同文本', '高', '(?:作品|成果|著作权|知识产权|创意|方案|设计)[^。；\n]{0,16}(?:归|属于)[^。；\n]{0,8}(?:公司|甲方|用人单位)[^。；\n]{0,6}(?:所有|享有)|(?:公司|甲方)[^。；\n]{0,10}(?:享有|拥有)[^。；\n]{0,8}(?:全部|所有)[^。；\n]{0,6}(?:著作权|知识产权)', '', '实习期间的作品归属可以约定，但一律无条件归公司、不署名不付酬属于显失公平，学生原创的设计、代码、文案最容易吃亏。', '参见《著作权法》第 11 条（一般职务作品著作权归作者）、第 18 条（署名权归作者）；《民法典》第 496 条（格式条款应提示说明）。', '要求写明：署名权归你，公司仅在业务范围内使用；超出范围需另行付费并征得同意。');
INSERT INTO trap (id, title, type, level, scene, signals, consequence, advice, source) VALUES
('T01', '入职先交 800 元「服装押金」，离职时以「工装磨损」为由不退', '押金类', '高', '本地一家连锁餐饮门店招兼职服务员，面试当天就让交服装押金和工牌费，说「离职全额退」。干了两个月要走，店长说工装洗坏了，押金不退。', ARRAY['入职当天收现金、不给正规收据', '押金写「可退」但没有退还条件', '离职时单方面认定「工装损耗」']::text[], '800 元押金打水漂；因为没有收据、没有书面协议，投诉时连「交过钱」都难举证。', '不交任何名目的入职费用。已交的保留转账记录、微信聊天、收据原件，直接向当地劳动保障监察部门反映。', '根据公开报道的餐饮兼职收费纠纷脱敏改写，公司名与人名已隐去。'),
('T02', '「先培训后上岗」：不交 6800 元培训费，就没有岗位', '培训贷', '高', '一家做电商运营的公司招实习生，面试通过后要求先参加 20 天「岗前实训」，费用 6800 元，说「实训结束直接上岗，做满半年返还」。实训结束后被告知「岗位已满」。', ARRAY['面试当场拿「培训协议」让你签字', '承诺「包上岗」「做满返还」', '培训地点与面试公司不是同一主体']::text[], '钱交了、岗没上，再去找对方已经不是同一家公司；退款条款没有写进任何纸质文件。', '岗前培训费用依法应由用人单位承担。凡是「先交钱再上岗」的，直接放弃这个机会；已经签了的，保留合同、付款凭证、宣传材料，向市场监管与劳动监察双向反映。', '根据公开报道的应届生培训费纠纷脱敏改写。'),
('T03', '「试岗七天不发工资，双向选择」', '无薪试岗', '高', '一家广告工作室招文案，说先试岗七天，看适不适合，七天里正常打卡上班、写稿交付，第八天通知「不合适」，七天工资一分没有。', ARRAY['明确说「试岗期无薪」', '试岗期照常打卡、接受排班', '「不合适」没有任何书面理由']::text[], '七天的劳动白干；若这七天里发生意外伤害，责任认定会更麻烦。', '只要实际提供了劳动就必须付报酬。试岗可以，但要签简短书面协议，写清试岗期限、日薪、工作内容；对方拒绝的一律不去。', '根据公开报道的「试岗期」用工争议脱敏改写。'),
('T04', '三方协议上手写一行「违约赔 5000」，学校那联没写', '违约金', '高', '签三方协议时，HR 说「公司统一流程」，在两份协议上手写补了一句「学生单方毁约需付违约金 5000 元」，学生那份没写。后来学生考上专升本想解约，公司拿出写着违约金的那份。', ARRAY['公司那份与学生那份内容不一致', '手写条款没有双方签字确认', '违约金金额明显高于实习报酬']::text[], '被要求赔付 5000 元，否则不给出具解约函，影响档案与派遣。', '签字前逐页比对两份文本，手写处必须双方签字或盖章；除服务期与竞业限制外，用人单位约定劳动者承担违约金缺乏依据，可据理力争。', '根据高校就业指导案例脱敏改写。'),
('T05', '实习协议写「不缴社保、不适用劳动法」', '社保', '高', '一家制造业企业招「实习生」，每天八小时、按月发薪、接受车间主任排班管理，协议里却写明「双方为实习关系，不缴纳社会保险，不适用劳动法律法规」。干了八个月，没有社保。', ARRAY['实际用工与正式员工无差别', '按月考勤、固定薪资', '协议用「实习」规避社保与合同']::text[], '期间生病住院全部自费；一旦被认定劳动关系，单位要补缴，但补缴流程与举证都要你跑。', '关系性质看实际用工，不看协议标题。保留排班表、工牌、工资流水、工作群记录，作为主张劳动关系的证据；可在离职后一年内申请劳动仲裁。', '根据公开劳动争议案例脱敏改写。'),
('T06', '月加班六十小时，加班费按「10 元/小时」包干', '加班', '高', '一家电商代运营公司旺季要求全员「大小周 + 每天到十点」，工资条上没有加班费，只在备注里写「加班补贴 300 元」。实际月加班时长超过 60 小时。', ARRAY['考勤由公司统一控制、无法自主下班', '工资条无加班费明细', '以「补贴」替代法定加班费']::text[], '长期超时工作，健康受损；离职时主张加班费，却因没有完整考勤记录而难以计算。', '法定上限是每月加班不超过 36 小时。自己每周截图保存考勤、排班、工作群通知；离职时一并主张加班费差额。', '根据公开报道的电商行业超时加班争议脱敏改写。'),
('T07', '合同里写「公司有权根据经营需要调整岗位与薪资」', '合同文本', '高', '入职时签的是「运营专员，月薪 4500」，合同附则有一条：公司有权根据经营需要调整乙方岗位、工作地点及薪酬。三个月后被调到仓库做打包，月薪降到 3200。', ARRAY['岗位与薪资条款后面跟着「公司有权单方调整」', '调岗没有书面通知与协商记录', '降薪后工资条无说明']::text[], '被迫接受降薪降岗，或者主动辞职且拿不到经济补偿。', '岗位与报酬是合同核心条款，变更需协商一致并书面确认。收到调岗通知时书面回复「不同意」，继续按原岗位出勤并留证。', '根据公开劳动争议案例脱敏改写。'),
('T08', '「离职要提前 90 天申请，否则扣一个月工资」', '离职', '高', '一家教育机构在劳动合同里约定，员工离职须提前 90 天书面申请，未满 90 天离岗按「擅自离岗」处理，扣发当月工资。学生毕业要离校，被迫放弃当月工资。', ARRAY['通知期远超 30 天', '扣工资作为离职惩罚', '以「自动离职」定性']::text[], '白白损失一个月工资；离职证明也被拖延。', '法定通知期是提前 30 日（试用期内 3 日）。按法定程序书面通知并完成交接，工资应结清；被扣可申请仲裁。', '根据公开报道的教培行业离职纠纷脱敏改写。'),
('T09', '签「保密协议」时被要求一并承诺「终身不得从事同行业」', '违约金', '中', '实习入职时签了一叠材料，其中一份《保密与竞业承诺》写着「离职后终身不得从事与本行业相关的工作」，没有提任何补偿。学生当时没细看。', ARRAY['竞业限制没有补偿条款', '限制期限写「终身」「长期」', '文件夹在一叠入职材料里催着签']::text[], '毕业后不敢投同行业岗位，担心被追责；实际上这类无补偿、无限期的条款很难被支持，但心理压力与沟通成本真实存在。', '竞业限制期限最长 2 年，且须按月支付经济补偿。签字前把「补偿金额、期限、范围」问清楚，没有补偿的可主张不受约束。', '根据公开的劳动法科普案例脱敏改写。'),
('T10', '「实习证明等离职后再开」，结果一直开不出来', '离职', '中', '学校要求提交实习证明才能认定学分。公司说「实习结束统一开」，结束后又说「等下个季度」，再问就没人回复了。', ARRAY['实习证明出具时间没有书面约定', '对接人频繁更换', '离职后联系不上']::text[], '学分认定被拖，影响毕业材料提交。', '入职时就问清出具时间与模板，写进实习协议的「其他约定」；离职当天当面拿到盖章证明，拿不到就请学校出具情况说明并保留沟通记录。', '根据高校实习管理中的常见问题脱敏改写。'),
('T11', '工资发现金、没有工资条，出了事说不清月薪多少', '合同文本', '中', '一家小型门店用微信转账发工资，没有工资条、没有考勤记录。干了四个月想主张拖欠的半个月工资，老板说「你是来帮忙的，不是员工」。', ARRAY['工资通过个人微信转账', '没有工资条与考勤记录', '协议里没写薪资数额']::text[], '连「是否存在劳动关系」「月薪多少」都要从头举证。', '要求银行代发并保留工资条；实在只能转账的，每月让对方在微信里确认「X 月工资 XXXX 元已发」，截图存档。', '根据公开的劳动监察案例脱敏改写。'),
('T12', '「表现好就转正」，转正条件永远在变', '合同文本', '中', '面试时说「实习三个月表现好就转正，转正后 6000」。三个月后说「再观察一个季度」，之后又说「今年编制收紧」。全程只有口头承诺，合同里写的是「实习补贴 2000 元/月」。', ARRAY['转正条件只在口头', '劳动合同／实习协议里没有转正条款', '转正时间一再顺延']::text[], '长期低薪，且没有可主张的违约依据。', '把转正条件、时间、转正后薪资写进书面协议；拿不到书面的，至少用微信让对方书面确认，并保存聊天记录。', '根据公开报道的实习转正纠纷脱敏改写。');
INSERT INTO cert (id, name, level, fit, signup, exam, fee, official, note, signup_url, exam_date) VALUES
('C01', '教师资格证', '门槛中等', '想进中小学、幼儿园、培训机构任教，或想给自己留一条「教育行业」的退路', '笔试与面试分两次报名，一般每年上下半年各一次；具体日期以官网当期公告为准', '笔试 → 面试 → 普通话水平测试 → 认定；各环节时间以官网当期公告为准', '笔试、面试按科目收费，各省标准不同；以官网当期公告为准', '教育部教育考试院（中小学教师资格考试网）', '笔试单科成绩有效期 2 年，全部合格后才能报面试；认定还需要体检与普通话证书。', '', ''),
('C02', '全国计算机等级考试（二级）', '门槛低', '非计算机专业想证明基础编程／办公能力，或作为简历上的「会用电脑」凭证', '一般每年多次开考，报名在考前一段时间开放；具体时间以 NCRE 官网当期公告为准', '上机考试，科目含 C 语言、Python、MS Office 等；考试时间以官网当期公告为准', '各省报名费不同，通常一百元上下；以官网当期公告为准', 'NCRE 官网（neea.edu.cn）', '二级证书长期有效；选科目比刷分更重要，先看目标岗位要求哪一科。', '', ''),
('C03', '大学英语四六级（CET-4 / CET-6）', '门槛低', '在校生通用；不少企业校招、专升本、部分岗位把四级当作硬门槛', '仅限在校生，由学校统一组织报名；具体时间以学校通知与 CET 官网当期公告为准', '每年上下半年各一次；具体日期以官网当期公告为准', '各省标准不同，通常几十元；以官网当期公告为准', 'CET 官网（neea.edu.cn）', '毕业后一般不能再考，在校期间尽量考掉；部分学校把四级与学位挂钩，先问教务处。', '', ''),
('C04', '普通话水平测试', '门槛低', '教师资格认定必备；播音、主持、部分服务类岗位也会看等级', '各省测试站分批组织，常年可报；具体批次以国家普通话水平测试在线报名系统当期公告为准', '机考，含读单音节字词、多音节词语、朗读短文、命题说话；时间以当期公告为准', '各省标准不同，通常几十元；以当期公告为准', '国家普通话水平测试在线报名系统', '教师资格一般要求二级乙等以上，语文教师要求二级甲等；证书全国通用、长期有效。', '', ''),
('C05', '初级会计职称', '门槛中等', '想进财务、出纳、代账岗位；非财会专业也可报考，是转行的低成本入口', '一般每年一次报名，报名与考试时间以财政部会计资格评价中心当期公告为准', '《初级会计实务》《经济法基础》两科，同一年度内全部合格才算通过；时间以当期公告为准', '各省标准不同，通常每科几十元；以当期公告为准', '财政部会计资格评价中心', '报考需要高中毕业及以上学历；两科必须同年通过，备考要一次安排两门。', '', ''),
('C06', '机动车驾驶证（C1 / C2）', '门槛低', '通用技能；部分销售、外勤、物流类岗位明确要求有驾照', '在驾校或车管所报名，全年可报；具体流程与受理时间以官网当期公告为准', '科目一理论 → 科目二场地 → 科目三道路 → 科目四理论；各地排考周期不同', '各地驾校报价差异大；以当地公示口径为准，具体以官网当期公告为准', '当地公安机关交通管理部门（车管所）', '学生假期集中学车人多，排考周期可能拉长；费用与课时一定要写进培训合同。', '', '');
